with flattened as (select id, customer_id, explode_outer(coupon_codes) as value from carts) select value, customer_id, sort_array(collect_set(value)) as value_list, count(*) filter (where value = 'WELCOME5') as welcome5_rows, size(collect_set(value)) as num_values, rank() over (partition by value order by size(collect_set(value)) desc) as num_values_rank from flattened group by value, customer_id having welcome5_rows < 1000 order by value
